57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
68	     * new owner's id, its assigned {@code customerCode}, its {@code registrationDate} and its
69	     * numeric {@code membershipLevel}.
70	     */
71	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
122	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
123	        rejectFutureRegistrationDate(registrationDate);
124	        if (registrationDate == null) {
125	            registrationDate = java.time.LocalDate.now();
126	        }
127	        registrationDate = toBusinessDay(registrationDate);
128	        owner.setRegistrationDate(registrationDate);
129	        rejectDailyLimitReached(registrationDate);
130	        rejectCityAtCapacity(owner.getCity());
131	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
132	        owner.setTelephone(telephone);
133	        String email = normalizeEmail(ownerFieldsDto.getEmail());
134	        owner.setEmail(email);
135	        owner.setPostcode(validatePostcode(owner.getCity(), ownerFieldsDto.getPostcode()));
136	        rejectDuplicateIdentity(owner);
137	        String region = Localities.region(owner.getPostcode(), owner.getCity());
138	        owner.setCustomerCode(assignCustomerCode(region, owner.getTelephone(), owner.getLastName()));
139	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
140	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
141	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
142	        this.clinicService.saveOwner(owner);
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
145	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
146	            ownerDto.getMembershipLevel());
147	        headers.setLocation(UriComponentsBuilder.newInstance()
148	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
149	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
150	    }
151	
152	    /**
153	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server
154	     * date (in the future). Only an explicitly supplied date is validated; a {@code null} date
155	     * (which later defaults to the server date) is accepted. The check is against the raw supplied
156	     * date, before any business-day adjustment.
157	     *
158	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
159	     * @throws FutureRegistrationDateException (400 Bad Request) if the supplied date is in the future
160	     */
161	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
162	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
163	            throw new FutureRegistrationDateException(registrationDate);
164	        }
165	    }
166	
167	    /**
168	     * The maximum number of owners that may be created in a single day. Creating an owner once this
169	     * many owners already carry today's {@code registrationDate} is rejected.
170	     */
171	    private static final int DAILY_OWNER_LIMIT = 100;
172	
173	    /**
174	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
175	     * given business day as their {@code registrationDate}. The count is keyed by the
176	     * business-day-adjusted registration date of the owner being created (see
177	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
178	     * with no {@code registrationDate} are ignored.
179	     *
180	     * @param registrationDate the business-day-adjusted registration date of the owner being created
181	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
182	     */
183	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
184	        long count = this.clinicService.findAllOwners().stream()
185	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
186	            .count();
187	        if (count >= DAILY_OWNER_LIMIT) {
188	            throw new DailyOwnerLimitException(registrationDate);
189	        }
190	    }
191	
192	    /**
193	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
194	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
195	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
196	     */
197	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
198	
199	    /**
200	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
201	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
202	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
203	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
204	     * owner being created is excluded (it has not yet been saved).
205	     *
206	     * @param registrationDate the business-day-adjusted registration date of the owner being created
207	     * @return {@code true} if more than the threshold of owners already carry this business day
208	     */
209	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
210	        long count = this.clinicService.findAllOwners().stream()
211	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
212	            .count();
213	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
214	    }
215	
216	    /**
217	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is moved forward to
218	     * the following Monday; a weekday is returned unchanged. This applies to the effective
219	     * registration date whether it was supplied in the request or defaulted to the server date, and
220	     * every value derived from the registration date uses the adjusted result.
221	     *
222	     * @param date the effective registration date
223	     * @return {@code date} itself when it is a weekday, otherwise the following Monday
224	     */
225	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
226	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
227	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
228	            date = date.plusDays(1);
229	        }
230	        return date;
231	    }
232	
233	    /**
234	     * The maximum number of owners a single city may contain. Creating an owner in a city that
235	     * already holds this many owners is rejected.
236	     */
237	    private static final int CITY_CAPACITY = 50;
238	
239	    /**
240	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
241	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
242	     * treated as empty).
243	     *
244	     * @param city the city of the owner being created
245	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
246	     */
247	    private void rejectCityAtCapacity(String city) {
248	        String cityValue = city == null ? "" : city;
249	        long count = this.clinicService.findAllOwners().stream()
250	            .filter(existing -> cityValue.equalsIgnoreCase(
251	                existing.getCity() == null ? "" : existing.getCity()))
252	            .count();
253	        if (count >= CITY_CAPACITY) {
254	            throw new CityAtCapacityException(city);
255	        }
256	    }
257	
258	    /**
259	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
260	     * REGION is the owner's canonical region (derived by preferring the postcode, see
261	     * {@link Localities#region(String, String)} — the same region derivation shared with the
262	     * {@code locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
263	     * the normalized (E.164) telephone concatenated with the last name (e.g. {@code 'NSW-3A7F9C2E'}).
264	     * There are no sequence numbers: the code is fully derived from the owner's own identity fields.
265	     *
266	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
267	     * @param telephone the owner's normalized (E.164) telephone
268	     * @param lastName the owner's last name
269	     * @return the assigned customer code
270	     */
271	    private String assignCustomerCode(String region, String telephone, String lastName) {
272	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
273	        String hash8 = sha256UpperHex(basis).substring(0, 8);
274	        return region + "-" + hash8;
275	    }
276	
277	    /**
278	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
279	     */
280	    private static String sha256UpperHex(String value) {
281	        try {
282	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
283	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
284	            StringBuilder sb = new StringBuilder(digest.length * 2);
285	            for (byte b : digest) {
286	                sb.append(String.format("%02X", b));
287	            }
288	            return sb.toString();
289	        }
290	        catch (java.security.NoSuchAlgorithmException e) {
291	            throw new IllegalStateException("SHA-256 not available", e);
292	        }
293	    }
294	
295	    /**
296	     * Counts how many existing owners share the given first and last name, compared
297	     * case-insensitively, at the time this owner is created. The value excludes the owner
298	     * being created (which has not yet been saved) and is stored on the new owner and returned
299	     * as its {@code namesakeCount}.
300	     *
301	     * @param firstName the first name of the owner being created
302	     * @param lastName the last name of the owner being created
303	     * @return the number of existing owners with the same first and last name
304	     */
305	    private int countNamesakes(String firstName, String lastName) {
306	        String first = firstName == null ? "" : firstName;
307	        String last = lastName == null ? "" : lastName;
308	        return (int) this.clinicService.findAllOwners().stream()
309	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
310	                && last.equalsIgnoreCase(existing.getLastName()))
311	            .count();
312	    }
313	
314	    /**
315	     * Counts how many existing owners belong to the same household as the owner being created, i.e.
316	     * share its {@code householdId} (derived by {@link Households#householdId} from the normalized last
317	     * name and address). The value excludes the owner being created (which has not yet been saved), so
318	     * the household's size after this create is this count plus one. It is stored on the new owner.
319	     *
320	     * @param lastName the last name of the owner being created
321	     * @param address the normalized address of the owner being created
322	     * @return the number of existing owners sharing this owner's household
323	     */
324	    private int countHouseholdMembers(String lastName, String address) {
325	        String householdId = Households.householdId(lastName, address);
326	        return (int) this.clinicService.findAllOwners().stream()
327	            .filter(existing -> householdId.equals(
328	                Households.householdId(existing.getLastName(), existing.getAddress())))
329	            .count();
330	    }
331	
332	    /**
333	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
334	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
335	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
336	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
337	     * {@code "+61412345678"}. The E.164 value is stored and returned.
338	     * <p>
339	     * The national-number length (the digits after the country code) is additionally validated for
340	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
341	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
342	     *
343	     * @param telephone the raw telephone as submitted
344	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
345	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
346	     *         or its national-number length is wrong for its country code
347	     */
348	    private String normalizeTelephone(String telephone) {
349	        String raw = telephone == null ? "" : telephone.trim();
350	        boolean hasCountryCode = raw.startsWith("+");
351	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
352	        if (hasCountryCode) {
353	            cleaned = cleaned.substring(1);
354	        }
355	        String digits;
356	        if (hasCountryCode) {
357	            digits = cleaned;
358	        } else {
359	            if (cleaned.startsWith("0")) {
360	                cleaned = cleaned.substring(1);
361	            }
362	            digits = "61" + cleaned;
363	        }
364	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
365	            throw new InvalidTelephoneException(telephone);
366	        }
367	        return "+" + digits;
368	    }
369	
370	    /**
371	     * Checks the national-number length of an E.164 digit string against its country code for the
372	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
373	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
374	     *
375	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
376	     * @return {@code true} if the national-number length is acceptable for the country code
377	     */
378	    private boolean hasValidNationalLength(String digits) {
379	        if (digits.startsWith("61")) {
380	            return digits.length() - 2 == 9;
381	        }
382	        if (digits.startsWith("1")) {
383	            return digits.length() - 1 == 10;
384	        }
385	        return true;
386	    }
387	
388	    /**
389	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
390	     * multi-character top-level label. Deliberately lenient about the exact character set while still
391	     * rejecting values that are clearly not addresses (e.g. missing '@').
392	     */
393	    private static final java.util.regex.Pattern EMAIL_PATTERN =
394	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
395	
396	    /**
397	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
398	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
399	     * lower-cased before being stored and returned.
400	     *
401	     * @param email the raw email as submitted, may be {@code null}
402	     * @return the lower-cased email, or {@code null} when none was supplied
403	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
404	     */
405	    private String normalizeEmail(String email) {
406	        if (email == null || email.isBlank()) {
407	            return null;
408	        }
409	        String trimmed = email.trim();
410	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
411	            throw new InvalidEmailException(email);
412	        }
413	        return trimmed.toLowerCase(java.util.Locale.ROOT);
414	    }
415	
416	    /**
417	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
418	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
419	     * {@link Localities#region}) accepts any 4-digit postcode.
420	     */
421	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
422	        "NSW", new int[] {2000, 2099},
423	        "VIC", new int[] {3000, 3099},
424	        "QLD", new int[] {4000, 4099});
425	
426	    /**
427	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
428	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
429	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
430	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
431	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
432	     *
433	     * @param city the owner's city, used to derive the region whose range constrains the postcode
434	     * @param postcode the raw postcode as submitted, may be {@code null}
435	     * @return the postcode when supplied, or {@code null} when none was supplied
436	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
437	     *         out of range for the city's region
438	     */
439	    private String validatePostcode(String city, String postcode) {
440	        if (postcode == null || postcode.isBlank()) {
441	            return null;
442	        }
443	        if (!postcode.matches("[0-9]{4}")) {
444	            throw new InvalidPostcodeException(postcode);
445	        }
446	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
447	        if (range != null) {
448	            int value = Integer.parseInt(postcode);
449	            if (value < range[0] || value > range[1]) {
450	                throw new InvalidPostcodeException(postcode);
451	            }
452	        }
453	        return postcode;
454	    }
455	
456	    /**
457	     * Common street-type abbreviations expanded to their full word during address normalization.
458	     */
459	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
460	        "ST", "STREET",
461	        "RD", "ROAD",
462	        "AVE", "AVENUE");
463	
464	    /**
465	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
466	     * whitespace collapse to a single space, the value is upper-cased and common street-type
467	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
468	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
469	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
470	     * for every address comparison (household duplicate detection and the shared household id).
471	     *
472	     * @param address the raw address as submitted
473	     * @return the normalized address
474	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
475	     */
476	    private String normalizeAddress(String address) {
477	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
478	        if (collapsed.isEmpty()) {
479	            throw new InvalidAddressException(address);
480	        }
481	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
482	        StringBuilder normalized = new StringBuilder(collapsed.length());
483	        for (int i = 0; i < tokens.length; i++) {
484	            if (i > 0) {
485	                normalized.append(' ');
486	            }
487	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
488	        }
489	        return normalized.toString();
490	    }
491	
492	    /**
493	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
494	     * is consolidated here onto the identity-bearing part of the derived {@code identityKey}: two
495	     * owners are duplicates when they share the same normalized telephone and the same normalized email
496	     * (a {@code null} email compared as an empty segment). Existing telephones are re-normalized to
497	     * E.164 and existing emails lower-cased before comparison, so equivalent values submitted in
498	     * different formats (e.g. national {@code "0412 345 678"} and international {@code "+61 412 345 678"})
499	     * still match.
500	     * <p>
501	     * The {@code householdId} is deliberately not part of this comparison: a household is a shared
502	     * grouping, so two members of the same household with different telephones have different
503	     * identities and are both allowed. Only owners with the same telephone and email collide.
504	     *
505	     * @param owner the owner being created, with its telephone and email already normalized
506	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity
507	     */
508	    private void rejectDuplicateIdentity(Owner owner) {
509	        String identity = personalIdentity(owner.getTelephone(), owner.getEmail());
510	        boolean duplicate = this.clinicService.findAllOwners().stream()
511	            .anyMatch(existing -> identity.equals(
512	                personalIdentity(toE164OrNull(existing.getTelephone()), existing.getEmail())));
513	        if (duplicate) {
514	            String householdId = Households.householdId(owner.getLastName(), owner.getAddress());
515	            throw new DuplicateIdentityException(
516	                Households.identityKey(owner.getTelephone(), owner.getEmail(), householdId));
517	        }
518	    }
519	
520	    /**
521	     * Builds the identity-bearing prefix of the {@code identityKey} used for duplicate detection:
522	     * the normalized telephone and email joined with {@code '|'}, lower-casing the email (the form it
523	     * is stored in, see {@link #normalizeEmail}) so addresses differing only in letter case still match.
524	     */
525	    private String personalIdentity(String telephone, String email) {
526	        String normalizedEmail = email == null ? "" : email.toLowerCase(java.util.Locale.ROOT);
527	        return (telephone == null ? "" : telephone) + "|" + normalizedEmail;
528	    }
529	
530	    /**
531	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
532	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
533	     * when its national-number length does not match its country code.
534	     */
535	    private String toE164OrNull(String telephone) {
536	        try {
537	            return normalizeTelephone(telephone);
538	        } catch (InvalidTelephoneException e) {
539	            return null;
540	        }
541	    }
542	
543	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
